"""Replace "space-newline" with "newline".

    Args:
        text (str): The string to work with

    Returns:
        The text with the appropriate fix.
    """
def space_newline_fix(text: Any) -> object {
    space_newline = ' \n';
    fix = '\n';
    while (space_newline in text) {
        text = text.replace(space_newline, fix);
    }
    return text;
}

"""
    Normalise the whitespace in the string

    :param text: string
    :return: string with whitespace normalised to single space
    """
def normalise_whitespace(text: Any) -> object {
    return " ".join(text.strip().split());
}

"""
    :type x: int
    :rtype: int
    """
def reverse(x: Any) -> object {
    sum1 = 0;
    if (x > 0) {
        n = len(str(x));
        for i in range(n) {
            rem = x % 10;
            x = x // 10;
            sum1 = (sum1 * 10) + rem;
        }
        return sum1;
    } elif (x < 0) {
        x = x * -1;
        n = len(str(x));
        for i in range(0, n) {
            rem = x % 10;
            x = x // 10;
            sum1 = (sum1 * 10) + rem;
        }
        return (sum1 * -1);
    } else {
        return x;
    }
}
